Q: Dynamically setting default in crosstalk filter with Javascript works for one variable, but not the other A: <p>In your <em>&quot;working as expected&quot;</em> 2015 and Jan are quoted:</p>
<pre><code>&lt;script&gt;
function filter_default(){
  document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;2015&quot;,false)
  document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;Jan&quot;,false)
}
$(document).ready(filter_default);
&lt;/script&gt;
</code></pre>
<p>they way you pass variables to JS, <strong>2015</strong> and <strong>Jan</strong> are not quoted. <strong>2015</strong> works since it's an integer, but <strong>Jan</strong> is an undefined variable.</p>
<pre><code>&gt; tags$script(HTML('
+ function filter_default(){
+   document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(',default_year,',false)
+   document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(',default_month,',false)
+ }
+ $(document).ready(filter_default);
+ '))
&lt;script&gt;
function filter_default(){
  document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue( 2015 ,false)
  document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue( Jan ,false)
}
$(document).ready(filter_default);
&lt;/script&gt;
</code></pre>
<p>So possible fixes could be <code>sprintf</code></p>
<pre><code>js &lt;- tags$script(HTML(sprintf('
function filter_default(){
  document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;%s&quot;,false)
  document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;%s&quot;,false)
}
$(document).ready(filter_default);
', default_year, default_month)))
</code></pre>
<p><code>paste0</code></p>
<pre><code>js_paste0 &lt;- tags$script(HTML(paste0('
function filter_default(){
  document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;',default_year,'&quot;,false)
  document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(',default_month,'&quot;,false)
}
$(document).ready(filter_default);
')))
</code></pre>
<p><a href="https://www.rdocumentation.org/packages/glue/versions/1.8.0/topics/glue" rel="nofollow noreferrer"><code>glue</code></a></p>
<pre><code>js_glue &lt;- tags$script(HTML(glue::glue('
function filter_default(){{
  document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;{default_year}&quot;,false)
  document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;{default_month}&quot;,false)
}}
$(document).ready(filter_default);
')))
</code></pre>
<hr />
<p><em><strong>Full Reprex</strong></em></p>
<pre><code>library(leaflet)
library(crosstalk)
library(geosphere)
library(htmltools)
library(bslib)
set.seed(42)
dat&lt;-data.frame(year=c(rep(2015,15),rep(2016,15),rep(2017,15)),
                month=factor(rep(c('Jan','Feb','Mar'),3), levels=c('Jan','Feb','Mar')),
                lon=randomCoordinates(n = 45)[,1],
                lat=randomCoordinates(n = 45)[,2])

sd &lt;- SharedData$new(dat)

dropdown_filter &lt;- filter_select(
  id = &quot;year_filter&quot;,
  label = &quot;&quot;,
  sharedData = sd,
  group = ~year,
  multiple=F
)

dropdown_filter2 &lt;- filter_select(
  id = &quot;month_filter&quot;,
  label = &quot;&quot;,
  sharedData = sd,
  group = ~month,
  multiple=F
)

map&lt;-leaflet() %&gt;%
  addTiles() %&gt;%
  addCircleMarkers(
    data = sd,
  ) 

default_year &lt;- min(unique(dat$year), na.rm=T)
default_month &lt;- as.character(dat$month[1])

js &lt;- tags$script(HTML(sprintf('
function filter_default(){
  document.getElementById(&quot;year_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;%s&quot;,false)
  document.getElementById(&quot;month_filter&quot;).getElementsByClassName(&quot;selectized&quot;)[0].selectize.setValue(&quot;%s&quot;,false)
}
$(document).ready(filter_default);
', default_year, default_month)))


browsable(tagList(js,
                  bscols(dropdown_filter,dropdown_filter2),
                  map
))
</code></pre>
